def features(X, degree=7):
    x1, x2 = X[:, 0], X[:, 1]
    cols = [np.ones(len(X))]
    for total in range(1, degree + 1):
        for a in range(total + 1):
            cols.append((x1 ** a) * (x2 ** (total - a)))
    return np.column_stack(cols)

